<?php
namespace App\Services\Payments; use App\Models\{Donation,PaymentGateway,PaymentWebhookLog}; use Illuminate\Support\Arr;
class PaymentWebhookService {
 public function process(PaymentGateway $gateway,array $payload,?string $signature): array { $secret=(string)Arr::get($gateway->settings,'webhook_secret',''); $raw=json_encode($payload,JSON_UNESCAPED_SLASHES); $valid=$secret!=='' && is_string($signature) && hash_equals(hash_hmac('sha256',$raw,$secret),$signature); $log=PaymentWebhookLog::create(['payment_gateway_id'=>$gateway->id,'provider'=>$gateway->provider,'event_type'=>Arr::get($payload,'event'),'external_reference'=>Arr::get($payload,'reference'),'signature'=>$signature,'signature_valid'=>$valid,'payload'=>$payload,'processing_status'=>$valid?'processing':'rejected']); if(!$valid){$log->update(['error_message'=>'Invalid webhook signature']); return ['ok'=>false,'status'=>401];}
  $reference=(string)(Arr::get($payload,'reference')??''); $donation=Donation::where('reference',$reference)->first(); if(!$donation){$log->update(['processing_status'=>'ignored','error_message'=>'Donation reference not found']); return ['ok'=>true,'status'=>202];}
  $status=strtolower((string)Arr::get($payload,'status','pending')); $map=['paid'=>'successful','success'=>'successful','successful'=>'successful','failed'=>'failed','cancelled'=>'cancelled','refunded'=>'refunded','pending'=>'pending']; $new=$map[$status]??'pending'; $attrs=['status'=>$new,'external_transaction_id'=>Arr::get($payload,'transaction_id'),'gateway_response'=>$payload]; if($new==='successful'){ $attrs['paid_at']=now(); $attrs['receipt_number']=$donation->receipt_number ?: 'COU-RCP-'.now()->format('Ymd').'-'.str_pad((string)$donation->id,7,'0',STR_PAD_LEFT); } $donation->update($attrs); $log->update(['processing_status'=>'processed']); return ['ok'=>true,'status'=>200,'donation'=>$donation->fresh()]; }
}
